				// Before record updated
function BeforeEdit(&$values, &$sqlValues, $where, &$oldvalues, &$keys, &$message, $inline, $pageObject)
{

		/******************************************************************************************
 * EVENTO: Before record updated (Edit Page)
 * MÓDULO: Solicitud de Vacaciones
 *
 * PROPÓSITO:
 * Este evento se ejecuta antes de actualizar una solicitud de vacaciones.
 *
 * Se utiliza para:
 *
 * 1. Validar los datos obligatorios del funcionario.
 * 2. Validar los campos y fechas de la solicitud.
 * 3. Recalcular los días hábiles solicitados.
 * 4. Validar antigüedad, saldo disponible y superposición de fechas.
 * 5. Controlar la corrección posterior a un rechazo de Jefatura.
 * 6. Controlar la corrección posterior a un rechazo de DGTH/RRHH.
 *
 * REGLAS DE CORRECCIÓN:
 *
 * JEFATURA:
 * - El funcionario puede corregir una solicitud rechazada por su superior
 *   inmediato una sola vez.
 * - Se controla mediante:
 *      intentos_correccion_jefatura
 *
 * DGTH / RRHH:
 * - El funcionario puede corregir una solicitud rechazada por DGTH/RRHH
 *   una sola vez.
 * - Se controla mediante:
 *      intentos_correccion
 *
 * Ambos contadores son independientes.
 *
 * Al corregir un rechazo de Jefatura:
 * - La solicitud vuelve a quedar pendiente de Jefatura.
 *
 * Al corregir un rechazo de DGTH/RRHH:
 * - Se conserva la aprobación previa de Jefatura.
 * - La solicitud vuelve a quedar pendiente únicamente de DGTH/RRHH.
 *
 * NOTA:
 * - $values    = nuevos valores enviados por el formulario.
 * - $oldvalues = valores existentes antes de la edición.
 * - return false cancela el guardado cuando alguna validación no se cumple.
 ******************************************************************************************/

/*==============================================================
=            FUNCIÓN AUXILIAR PARA DEPURACIÓN                  =
==============================================================*/
/**
 * Imprime información en la consola del navegador.
 * Útil SOLO en desarrollo para verificar valores.
 *
 * @param mixed  $data    Datos a mostrar
 * @param string $context Texto descriptivo del contexto
 */
//function debug_to_console($data, $context = 'Debug in Console') {
//	ob_start();
//	$output  = 'console.info(\'' . $context . ':\');';
//	$output .= 'console.log(' . json_encode($data) . ');';
//	$output  = sprintf('<script>%s</script>', $output);
//	echo $output;
//}

/*==============================================================
=      INCLUSIÓN DE FUNCIONES ESPECÍFICAS DE VACACIONES       =
==============================================================*/
require_once(getabspath("include/view-vacacion-funciones.php"));


/*==============================================================
=        FUNCIÓN PARA GENERAR MENSAJES DE ERROR VISUAL        =
==============================================================*/
/**
 * Genera un bloque HTML estilizado para mostrar errores al usuario.
 * Permite incluir:
 * @param string $titulo
 * @param string $descripcion
 * @param array  $items Lista opcional de campos faltantes
 * @param string $footer Texto adicional (ej: instrucciones)
 */
function generarMensajeError($titulo, $descripcion, $items = [], $footer = "") {
	$htmlItems = "";
	
	if (!empty($items)) {
		$htmlItems .= "<ul style='margin-top:8px'>";
		foreach ($items as $item) {
			$htmlItems .= "<li>$item</li>";
		}
		$htmlItems .= "</ul>";
	}
	
	return "
	<div style='
		background:#f8d7da;
		color:#721c24;
		padding:14px;
		border-radius:12px;
		border-left:6px solid #dc3545;
	'>
		<b>❌ $titulo</b>
		<br><br>
		<b>$descripcion</b>
		$htmlItems
		$footer
	</div>";
}

/*
 * ============================================================
 * VALIDAR Y FORZAR FUNCIONARIO DE LA SESIÓN EN EDIT
 * ============================================================
 *
 * No confiar en id_funcionario recibido desde el formulario.
 */
if (!Security::hasLogin()) {
	$message = generarMensajeError(
		"No es posible actualizar la solicitud.",
		"No se pudo identificar una sesión válida.",
		[],
		"Inicie sesión nuevamente e intente otra vez."
	);
	return false;
}

$currentUser = Security::currentUserData();
$userPersonal = isset($currentUser["usu_personal"]) ? (int)$currentUser["usu_personal"] : 0;
$idFuncionarioOriginal = isset($oldvalues["id_funcionario"]) ? (int)$oldvalues["id_funcionario"] : 0;

/*
 * La solicitud debe pertenecer al funcionario autenticado.
 */
if ($userPersonal <= 0 || $idFuncionarioOriginal <= 0 || $userPersonal !== $idFuncionarioOriginal) {
	$message = generarMensajeError(
		"No es posible actualizar la solicitud.",
		"La solicitud indicada no pertenece al funcionario autenticado."
	);
	return false;
}

/*
 * Forzar nuevamente el funcionario correcto.
 *
 * Aunque el navegador envíe otro id_funcionario,
 * el servidor utilizará siempre el funcionario de la sesión.
 */
$values["id_funcionario"] = $userPersonal;



/**
 * ============================================================
 * 👤 VALIDACIÓN DE DATOS DEL PERFIL DEL FUNCIONARIO
 * ============================================================
 * Se valida que el funcionario tenga datos básicos completos.
 * Estos datos NO se cargan en el formulario directamente,
 * pero son necesarios para procesar correctamente el permiso.
 * Verifica que el usuario tenga completos los datos básicos
 * antes de permitir enviar una solicitud.
 */
// (descripcion_tipo_vinculacion: es de solo lectura(READONLY) por eso no se envia por POST, solucion provisoria enviar el descripcion_dependencia_edit).
$camposRequeridosPerfil = [
	"descripcion_dependencia_edit" => "Dependencia",
	"tipo_vinculacion" => "Tipo de vinculación"
];

$faltantesPerfil = [];

foreach ($camposRequeridosPerfil as $campo => $label) {
	if (!isset($values[$campo]) || trim($values[$campo]) === "") {
		$faltantesPerfil[] = $label;
	}
}

// ⛔ Si faltan datos → detener proceso
if (!empty($faltantesPerfil)) {
	$message = generarMensajeError(
		"No es posible enviar la solicitud de permiso.",
		"Faltan completar los siguientes datos de tu perfil:",
		$faltantesPerfil,
		"Por favor, comunícate con el área de <b>Recursos Humanos</b> para actualizar tu información."
	);
	
	return false; // ⛔ DETIENE TODO
}
/**
 * ============================================================
 * 🚫 FIN DE VALIDACIÓN DE PERFIL DEL FUNCIONARIO
 * ============================================================
 */


/**
 * ============================================================
 * 📝 VALIDACIÓN DE CAMPOS DEL FORMULARIO
 * ============================================================
 * Verifica que todos los campos obligatorios estén completos.
 */
$camposRequeridosFormulario = [
	"motivo_id" => "Tipo de permiso o justificación",
	"fecha_desde" => "Fecha desde",
	"hora_desde" => "Hora de inicio",
	"fecha_hasta" => "Fecha hasta",
	"hora_hasta" => "Hora de fin",
	"email_jefe_id" => "Correo electrónico del superior inmediato"
];

$faltantesFormulario = [];

foreach ($camposRequeridosFormulario as $campoForm => $labelForm) {
	if (!isset($values[$campoForm]) || trim($values[$campoForm]) === "") {
		$faltantesFormulario[] = $labelForm;
	}
}

// ⛔ Si faltan datos → detener proceso
if (!empty($faltantesFormulario)) {
	$message = generarMensajeError(
		"No es posible enviar la solicitud de permiso.",
		"Falta completar los siguientes datos del formulario:",
		$faltantesFormulario,
		"Por favor, completa los campos obligatorios del formulario."
	);

	return false; // ⛔ DETIENE TODO
}
/**
 * ============================================================
 * 🚫 FIN DE VALIDACIÓN DE CAMPOS DEL FORMULARIO
 * ============================================================
 */


$motivo_id = $values["motivo_id"];

/*==============================================================
=     CÁLCULO OFICIAL DE DÍAS HÁBILES DE VACACIONES - EDIT    =
==============================================================*/

/*
 * IMPORTANTE:
 * El campo vac_dias_pedidos que se muestra en pantalla mediante
 * AJAX es únicamente informativo.
 *
 * Aquí el servidor vuelve a calcular oficialmente los días
 * hábiles para evitar depender de un valor enviado por el
 * navegador.
 */
$fechaDesdeVacacion = isset($values["fecha_desde"]) ? trim((string)$values["fecha_desde"]) : "";
$fechaHastaVacacion = isset($values["fecha_hasta"]) ? trim((string)$values["fecha_hasta"]) : "";

/*
 * Validar que existan ambas fechas.
 */
if ($fechaDesdeVacacion === "" || $fechaHastaVacacion === "") {
	$message = generarMensajeError(
		"No se pudo actualizar la solicitud de vacaciones.",
		"Debe indicar correctamente la fecha desde y la fecha hasta."
	);
	return false;
}

/*
 * Normalizar las fechas recibidas por PHPRunner.
 */
try {
	$fechaDesdeObj = new DateTime($fechaDesdeVacacion);
	$fechaHastaObj = new DateTime($fechaHastaVacacion);
} catch (Exception $e) {
	$message = generarMensajeError(
		"No se pudo actualizar la solicitud de vacaciones.", 
		"Las fechas ingresadas no tienen un formato válido."
	);
	return false;
}

$fechaDesdeVacacion = $fechaDesdeObj->format("Y-m-d");
$fechaHastaVacacion = $fechaHastaObj->format("Y-m-d");

/*
 * La fecha inicial nunca puede ser posterior a la final.
 */
if ($fechaDesdeObj > $fechaHastaObj) {
	$message = generarMensajeError(
		"No se pudo actualizar la solicitud de vacaciones.", 
		"La fecha desde no puede ser posterior a la fecha hasta.");
	return false;
}

/*
 * Cálculo oficial:
 *
 * - lunes a viernes
 * - excluye feriados registrados en public.feriados
 */
$sqlDiasVacaciones = DB::PrepareSQL(
	"SELECT COUNT(*)::int AS dias_habiles
		FROM generate_series(':1'::date, ':2'::date, INTERVAL '1 day') AS d(fecha)
		WHERE EXTRACT(ISODOW FROM d.fecha) BETWEEN 1 AND 5
		AND NOT EXISTS (
							SELECT 1
							FROM public.feriados f
							WHERE f.fer_fecha::date = d.fecha::date
		)",
	$fechaDesdeVacacion,
	$fechaHastaVacacion
);

$rsDiasVacaciones = DB::Query($sqlDiasVacaciones);
if (!$rsDiasVacaciones) {
	$message = generarMensajeError(
		"No se pudo actualizar la solicitud de vacaciones.",
		"No fue posible calcular los días hábiles solicitados."
	);
	return false;
}

$rowDiasVacaciones = $rsDiasVacaciones->fetchAssoc();
if (!$rowDiasVacaciones) {
	$message = generarMensajeError(
		"No se pudo actualizar la solicitud de vacaciones.", 
		"No fue posible obtener el resultado del cálculo de días.");
	return false;
}

$diasHabilesVacaciones = (int)$rowDiasVacaciones["dias_habiles"];

/*
 * Por seguridad, una vacación no puede quedar con cero días.
 */
if ($diasHabilesVacaciones <= 0) {
	$message = generarMensajeError(
		"No se pudo actualizar la solicitud de vacaciones.", 
		"El período seleccionado no contiene días hábiles."
	);
	return false;
}

$values["vac_dias_pedidos"] = $diasHabilesVacaciones;
$values["vac_periodo_solicitado"] = (int)$fechaDesdeObj->format("Y");

/*==============================================================
=   VALIDACIÓN: MÍNIMO 5 DÍAS HÁBILES DE VACACIONES           =
==============================================================*/
/*
 * Las vacaciones deben solicitarse por un mínimo
 * de 5 días hábiles consecutivos dentro del rango indicado.
 *
 * $diasHabilesVacaciones ya fue recalculado oficialmente
 * por el servidor, por lo que NO dependemos del valor
 * enviado desde el navegador.
 */
if ($diasHabilesVacaciones < 5) {
	$message = generarMensajeError(
		"No se pudo actualizar la solicitud de vacaciones.",
		"La cantidad de días hábiles solicitados no cumple con el mínimo permitido.",
		[
			"<strong>Días hábiles solicitados: " . $diasHabilesVacaciones . "</strong>",
			"<strong>El mínimo permitido para una solicitud de vacaciones es de 5 días hábiles.</strong>"
    ],
    "<br><b>Modifica el período solicitado e intenta nuevamente.</b>"
	);
	return false;
}


/*==============================================================
= VALIDACIÓN: INICIO DE VACACIONES EN PRIMER DÍA HÁBIL SEMANAL =
==============================================================*/

/*
 * Regla:
 *
 * - Normalmente la vacación debe comenzar un lunes.
 * - Si el lunes es feriado, puede comenzar el siguiente
 *   día hábil de esa misma semana.
 * - Si existen varios feriados consecutivos desde el lunes,
 *   se permite comenzar en el primer día hábil posterior.
 *
 * Ejemplos:
 *
 * Lunes hábil
 *   → debe comenzar lunes.
 *
 * Lunes feriado
 *   → puede comenzar martes, si martes es hábil.
 *
 * Lunes y martes feriados
 *   → puede comenzar miércoles, si miércoles es hábil.
 */
$sqlInicioVacacion = DB::PrepareSQL(
	"WITH datos AS (SELECT ':1'::date AS fecha_inicio,
															date_trunc('week', ':1'::date)::date AS lunes_semana
											)
	SELECT	CASE
						/*
							* La fecha elegida debe ser un día de lunes a viernes
							* y además no debe ser feriado.
							*/
					WHEN EXTRACT(ISODOW FROM fecha_inicio) NOT BETWEEN 1 AND 5
						THEN false
					WHEN EXISTS (
						SELECT 1
						FROM public.feriados f
						WHERE f.fer_fecha::date = fecha_inicio
					)
						THEN false
						/*
							* No puede existir ningún día hábil anterior,
							* desde el lunes de esa semana hasta el día
							* anterior a la fecha elegida.
							*
							* Si existe uno, significa que la vacación
							* debió comenzar antes.
						*/
					WHEN EXISTS (
						SELECT 1
						FROM generate_series(
							lunes_semana,
							fecha_inicio - 1,
							INTERVAL '1 day'
						) AS d(fecha)
						WHERE EXTRACT(ISODOW FROM d.fecha) BETWEEN 1 AND 5
						AND NOT EXISTS (
							SELECT 1
							FROM public.feriados f
							WHERE f.fer_fecha::date = d.fecha::date)
					)
						THEN false
					ELSE true
					END AS inicio_valido
    FROM datos",
    $fechaDesdeVacacion
);

$rsInicioVacacion = DB::Query($sqlInicioVacacion);

if (!$rsInicioVacacion) {
	$message = generarMensajeError(
		"No se pudo actualizar la solicitud de vacaciones.",
		"No fue posible validar la fecha de inicio de las vacaciones."
	);
	
	return false;
}

$rowInicioVacacion = $rsInicioVacacion->fetchAssoc();
$inicioVacacionValido = $rowInicioVacacion
	&& (
		$rowInicioVacacion["inicio_valido"] === true
			|| $rowInicioVacacion["inicio_valido"] === "t"
			|| $rowInicioVacacion["inicio_valido"] === "1"
			|| $rowInicioVacacion["inicio_valido"] === 1
		);

if (!$inicioVacacionValido) {
	$message = generarMensajeError(
		"No se pudo actualizar la solicitud de vacaciones.",
		"La fecha de inicio seleccionada no corresponde al primer día hábil de la semana.",
		[
			"<strong>Fecha de inicio seleccionada: " . date("d/m/Y", strtotime($fechaDesdeVacacion)) . "</strong>",
			"<strong>Las vacaciones deben comenzar un lunes o, si el lunes es feriado, el siguiente día hábil.</strong>"
		],
		"<br><b>Modifica la fecha de inicio e intenta nuevamente.</b>"
	);
	
	return false;
}


/*==============================================================
=     VALIDACIÓN DE SUPERPOSICIÓN DE VACACIONES - EDIT         =
==============================================================*/

/*
 * Al editar una solicitud debemos impedir que el nuevo período
 * se superponga con otra solicitud activa del mismo funcionario.
 *
 * IMPORTANTE:
 * se excluye la propia solicitud que estamos editando.
 */

$idSolicitudActual = 0;

if (isset($oldvalues["id"])) {
	$idSolicitudActual = (int)$oldvalues["id"];
} elseif (isset($values["id"])) {
	$idSolicitudActual = (int)$values["id"];
}

if ($idSolicitudActual <= 0) {
	$message = generarMensajeError(
		"No se pudo actualizar la solicitud de vacaciones.",
		"No fue posible identificar la solicitud que se está editando."
	);
	return false;
}

$idFuncionarioSuperposicion = (int)$values["id_funcionario"];
$sqlSuperposicionVacaciones = "
	SELECT pf.id,
					pf.fecha_desde,
					pf.fecha_hasta,
					pf.estado,
					pf.resultado_decision,
					pf.rrhh_resultado_decision
	FROM rrhh_permisos.permisos_funcionarios pf
	WHERE pf.id_funcionario = " . $idFuncionarioSuperposicion . "
	AND pf.motivo_id = '1'
	AND pf.id <> " . $idSolicitudActual . "
	AND (
				(pf.estado = 'PENDIENTE' AND pf.resultado_decision = 'PENDIENTE')
				OR
				(
					pf.estado = 'APROBADO'
					AND pf.resultado_decision = 'APROBADO'
					AND pf.rrhh_resultado_decision IN ('PENDIENTE', 'APROBADO')
				)
		  )
	AND pf.fecha_desde <= '" . $fechaHastaVacacion . "'::date
	AND pf.fecha_hasta >= '" . $fechaDesdeVacacion . "'::date
	LIMIT 1
";

$rsSuperposicionVacaciones = DB::Query($sqlSuperposicionVacaciones);
if (!$rsSuperposicionVacaciones) {
	$message = generarMensajeError(
		"No se pudo actualizar la solicitud de vacaciones.",
		"No fue posible verificar si existen otras vacaciones superpuestas."
	);
	return false;
}

$rowSuperposicionVacaciones = $rsSuperposicionVacaciones->fetchAssoc();
if ($rowSuperposicionVacaciones) {
	$idSolicitudSuperpuesta = (int)$rowSuperposicionVacaciones["id"];
	$fechaDesdeSuperpuesta = date("d/m/Y", strtotime($rowSuperposicionVacaciones["fecha_desde"]));
	$fechaHastaSuperpuesta = date("d/m/Y", strtotime($rowSuperposicionVacaciones["fecha_hasta"]));
	
	$message = generarMensajeError(
		"No se pudo actualizar la solicitud de vacaciones.",
		"El período seleccionado se superpone con otra solicitud de vacaciones activa.",
		[
